import{_ as e,c as r,o as a,a as i}from"./app.19f3f8f0.js";const u=JSON.parse('{"title":"감정 앱","description":"","frontmatter":{},"headers":[{"level":2,"title":"설명","slug":"설명","link":"#설명","children":[]},{"level":2,"title":"주요 기능","slug":"주요-기능","link":"#주요-기능","children":[]},{"level":2,"title":"작동 방식","slug":"작동-방식","link":"#작동-방식","children":[]},{"level":2,"title":"언제 어디서나 영감을 얻으세요","slug":"언제-어디서나-영감을-얻으세요","link":"#언제-어디서나-영감을-얻으세요","children":[]}],"relativePath":"inspire/index.md"}'),t={name:"inspire/index.md"},n=i('<h1 id="감정-앱" tabindex="-1">감정 앱 <a class="header-anchor" href="#감정-앱" aria-hidden="true">#</a></h1><h1 id="지원-이메일" tabindex="-1">지원 이메일 <a class="header-anchor" href="#지원-이메일" aria-hidden="true">#</a></h1><p><a href="mailto:main@tl-dr.in" target="_blank" rel="noreferrer">main@tl-dr.in</a></p><h2 id="설명" tabindex="-1">설명 <a class="header-anchor" href="#설명" aria-hidden="true">#</a></h2><p>신의 감정을 이해하고 그에 맞는 맞춤형 조언과 위로를 제공하는 AI 기반의 감정 지원 앱입니다. 최첨단 언어 모델 AI를 활용하여, 이 앱은 &quot;제미니(Gemini)&quot;라는 코드명의 생성 AI를 통해 사용자에게 맞춤형 메시지, 인용문, 문구를 생성하여 고양시키고 동기부여를 제공합니다.</p><h2 id="주요-기능" tabindex="-1">주요 기능 <a class="header-anchor" href="#주요-기능" aria-hidden="true">#</a></h2><ul><li><p><strong>개인화된 영감</strong>: 앱은 사용자의 현재 감정과 상태를 분석하여 이에 맞는 맞춤형 메시지를 생성합니다.</p></li><li><p><strong>제미니 AI</strong>: 앱의 핵심은 고급 생성 AI인 제미니에 있으며, 이는 지속적으로 학습하고 적응하여 점점 더 관련성 높고 효과적인 콘텐츠를 제공합니다.</p></li><li><p><strong>맞춤 설정 옵션</strong>: 사용자는 자신이 받는 영감 메시지의 주제, 토픽 또는 톤을 선택하여 경험을 맞춤 설정할 수 있습니다.</p></li><li><p><strong>자동 푸시 알림</strong> : 자동으로 맞춤형 메시지를 푸시 알림으로 전송하여 지속적인 지원을 제공합니다.</p></li></ul><h2 id="작동-방식" tabindex="-1">작동 방식 <a class="header-anchor" href="#작동-방식" aria-hidden="true">#</a></h2><ol><li><p><strong>감정 분석</strong>: 앱은 정교한 알고리즘을 사용하여 사용자의 현재 감정 상태를 분석합니다. 이 분석은 기분, 톤, 문맥 등의 요소를 고려합니다.</p></li><li><p><strong>제미니 AI 생성</strong>: 감정 분석을 기반으로, 제미니는 자연어 생성 기술을 사용하여 맞춤형 메시지를 생성합니다. 이 메시지들은 사용자의 감정에 공감하며 관련된 영감을 제공합니다.</p></li><li><p><strong>전달</strong>: 생성된 메시지는 앱 인터페이스나 푸시 알림을 통해 사용자에게 전달되어, 언제든지 영감을 얻을 수 있도록 합니다.</p></li></ol><h2 id="언제-어디서나-영감을-얻으세요" tabindex="-1">언제 어디서나 영감을 얻으세요 <a class="header-anchor" href="#언제-어디서나-영감을-얻으세요" aria-hidden="true">#</a></h2><p><strong>감정</strong> 앱을 통해 사용자는 현재 감정 상태에 맞춘 지속적인 동기부여와 격려를 받을 수 있습니다. 기분이 저조하여 활력이 필요할 때나 새로운 도전에 영감을 얻고자 할 때, 감정는 적시에 완벽한 말을 제공하여 항상 함께합니다.</p>',11),l=[n];function s(d,o,h,c,p,_){return a(),r("div",null,l)}const f=e(t,[["render",s]]);export{u as __pageData,f as default};
